def clean_alphanumeric(value: Any) -> str:
    if value is None or pd.isna(value):
        return ""
    text = str(value).strip().upper()
    text = re.sub(r"^([0-9]+)\.0+$", r"\1", text)
    return re.sub(r"[^A-Z0-9]", "", text)


def clean_po(value: Any) -> str:
    if value is None or pd.isna(value):
        return ""
    text = str(value).strip().upper()
    text = re.sub(r"^([0-9]+)\.0+$", r"\1", text)
    text = re.sub(r"^P\.?\s*O\.?(?:\s*[#:\-]\s*|\s+|(?=\d))", "", text)
    return re.sub(r"[^A-Z0-9]", "", text)


def parse_amount_cents(value: Any) -> Optional[int]:
    """Return exact signed cents, or None when the source amount is invalid."""
    if value is None or pd.isna(value):
        return None
    if isinstance(value, bool):
        return None
    text = str(value).strip()
    if not text:
        return None
    negative_parentheses = text.startswith("(") and text.endswith(")")
    text = text.replace("$", "").replace(",", "").replace(" ", "")
    if negative_parentheses:
        text = "-" + text[1:-1]
    try:
        amount = Decimal(text).quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)
        if not amount.is_finite():
            return None
        return int(amount * 100)
    except (InvalidOperation, ValueError, TypeError):
        return None


def cents_to_float(value: Any) -> float:
    if value is None or pd.isna(value):
        return 0.0
    return float(Decimal(int(value)) / Decimal(100))


def cents_or_zero(value: Any) -> int:
    return 0 if value is None or pd.isna(value) else int(value)


def valid_cents(value: Any) -> bool:
    return value is not None and not pd.isna(value)


def numeric_sum(series: pd.Series) -> float:
    return cents_to_float(sum(int(c) for c in series.map(parse_amount_cents) if valid_cents(c)))


def numeric_quantity_sum(series: pd.Series) -> float:
    return float(pd.to_numeric(series, errors="coerce").fillna(0).sum())


def fallback_product_match(value: Any) -> Optional[str]:
    cleaned = clean_alphanumeric(value)
    if not cleaned:
        return None
    exact: dict[str, str] = {}
    for standard, variants in PRODUCT_LEXICON.items():
        exact[clean_alphanumeric(standard)] = standard
        for variant in variants:
            exact[clean_alphanumeric(variant)] = standard
    if cleaned in exact:
        return exact[cleaned]
    # Conservative containment only. Product classification never determines
    # a financial match, so a fallback miss simply remains unclassified.
    candidates = [
        (len(alias), standard)
        for alias, standard in exact.items()
        if len(alias) >= 5 and (alias in cleaned or cleaned in alias)
    ]
    return max(candidates, default=(0, None))[1]


def product_match(value: Any) -> Optional[str]:
    if _engine_product_match is not None:
        try:
            return _engine_product_match(value)
        except Exception:
            pass
    return fallback_product_match(value)


def parse_fiscal_period(value: Any, default_year: int) -> tuple[Optional[int], Optional[int]]:
    if value is None or pd.isna(value):
        return None, None
    text = str(value).strip().upper()
    match = re.fullmatch(
        r"(?:PD|P|PERIOD)?\s*(\d{1,2})(?:\.0+)?(?:\s*[-/]\s*(\d{4}|\d{2}))?",
        text,
    )
    if not match:
        return None, None
    period = int(match.group(1))
    year_text = match.group(2)
    year = int(year_text) if year_text else int(default_year)
    if year_text and len(year_text) == 2:
        year += 2000
    if not 1 <= period <= 13 or not 1900 <= year <= 2199:
        return None, None
    return period, year


def fiscal_label(value: Any, default_year: int) -> str:
    period, year = parse_fiscal_period(value, default_year)
    return f"P{period:02d}-{year}" if period is not None else "Unspecified"


def format_central_timestamp(value: datetime) -> str:
    """Format a timezone-aware report timestamp in U.S. Central Time."""
    if value.tzinfo is None:
        value = value.replace(tzinfo=timezone.utc)
    central_value = value.astimezone(CENTRAL_TIMEZONE)
    return central_value.strftime("%Y-%m-%d %I:%M:%S %p %Z")


def excel_safe(value: Any) -> Any:
    """Convert values safely for Excel and neutralize formula-like source text."""
    if value is None:
        return None
    try:
        if pd.isna(value):
            return None
    except (TypeError, ValueError):
        pass
    if isinstance(value, pd.Timestamp):
        value = value.to_pydatetime()
    if isinstance(value, datetime) and value.tzinfo is not None:
        value = value.replace(tzinfo=None)
    if isinstance(value, Decimal):
        return float(value)
    if hasattr(value, "item"):
        try:
            value = value.item()
        except Exception:
            pass
    if isinstance(value, (list, tuple, set)):
        value = "; ".join(str(item) for item in value)
    if isinstance(value, str):
        # Excel treats strings beginning with these characters as formulas or
        # external commands in several import/opening contexts. Prefixing an
        # apostrophe forces a literal text cell without changing its display.
        if value.lstrip().startswith(("=", "+", "-", "@")):
            return "'" + value
    return value


def file_sha256(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()


def _header_score(values: Iterable[Any], source: str) -> int:
    tokens = {str(value).strip().upper() for value in values if value is not None and not pd.isna(value)}
    joined = " | ".join(tokens)
    score = len(tokens)
    if source == "QB":
        for term, weight in (("AMOUNT", 10), ("P.O", 7), ("PO", 5), ("NUM", 5), ("QTY", 4), ("MEMO", 4)):
            if term in joined:
                score += weight
    else:
        for term, weight in (("OHTOTA", 12), ("OHOBNO", 8), ("OHDESC", 8), ("AMOUNT", 8), ("INVOICE", 5)):
            if term in joined:
                score += weight
    return score


@st.cache_data(show_spinner=False, max_entries=8)
def detect_header_row(file_bytes: bytes, filename: str, source: str) -> int:
    suffix = Path(filename).suffix.lower()
    stream = io.BytesIO(file_bytes)
    if suffix == ".csv":
        probe = pd.read_csv(stream, header=None, nrows=25, dtype=object)
    else:
        probe = pd.read_excel(stream, header=None, nrows=25, dtype=object)
    if probe.empty:
        return 0
    scores = [_header_score(probe.iloc[row].tolist(), source) for row in range(len(probe))]
    return int(max(range(len(scores)), key=lambda idx: scores[idx]))


def _header_token(value: Any) -> str:
    if value is None:
        return ""
    try:
        if pd.isna(value):
            return ""
    except (TypeError, ValueError):
        pass
    return re.sub(r"[^A-Z0-9]", "", str(value).strip().upper())


def _substantive_cells(frame: pd.DataFrame) -> pd.DataFrame:
    if frame.empty:
        return pd.DataFrame(False, index=frame.index, columns=frame.columns)
    text_present = frame.astype("string").apply(lambda column: column.str.strip().ne(""))
    return (frame.notna() & text_present.fillna(False)).astype(bool)


def _unique_source_headers(values: list[Any]) -> tuple[list[str], list[str], list[str]]:
    headers: list[str] = []
    original_headers: list[str] = []
    duplicate_renames: list[str] = []
    occurrences: dict[str, int] = defaultdict(int)
    for position, value in enumerate(values, 1):
        try:
            missing = value is None or bool(pd.isna(value))
        except (TypeError, ValueError):
            missing = value is None
        original = "" if missing else str(value).strip()
        base = original or f"Unnamed Column {position}"
        key = _header_token(base) or f"UNNAMEDCOLUMN{position}"
        occurrences[key] += 1
        header = base if occurrences[key] == 1 else f"{base} [{occurrences[key]}]"
        if occurrences[key] > 1:
            duplicate_renames.append(f"{base} renamed to {header}")
        headers.append(header)
        original_headers.append(original)
    return headers, original_headers, duplicate_renames


@st.cache_data(show_spinner=False, max_entries=8)
def read_source_file(file_bytes: bytes, filename: str, header_row: int) -> pd.DataFrame:
    suffix = Path(filename).suffix.lower()
    if suffix not in {".csv", ".xlsx"}:
        raise ValueError("Only CSV and XLSX source files are supported.")
    stream = io.BytesIO(file_bytes)
    if suffix == ".csv":
        raw = pd.read_csv(stream, header=None, dtype=object)
    else:
        raw = pd.read_excel(stream, header=None, dtype=object)
    if raw.empty or header_row < 0 or header_row >= len(raw):
        raise ValueError("The selected header row is outside the populated source data.")

    headers, original_headers, duplicate_renames = _unique_source_headers(raw.iloc[header_row].tolist())
    frame = raw.iloc[header_row + 1:].copy()
    frame.columns = headers

    populated = _substantive_cells(frame)
    blank_rows_removed = int((~populated.any(axis=1)).sum())
    frame = frame.loc[populated.any(axis=1)].copy()

    tokenized = frame.apply(lambda column: column.map(_header_token))
    expected = pd.Series([_header_token(value) for value in original_headers], index=headers)
    header_matches = tokenized.eq(expected, axis="columns") & expected.ne("")
    nonblank_tokens = tokenized.ne("").sum(axis=1)
    repeated_header_mask = (
        nonblank_tokens.ge(2)
        & header_matches.sum(axis=1).ge(2)
        & header_matches.sum(axis=1).div(nonblank_tokens.where(nonblank_tokens.ne(0), 1)).ge(0.60)
    )
    repeated_header_rows_removed = int(repeated_header_mask.sum())
    frame = frame.loc[~repeated_header_mask].copy()

    populated = _substantive_cells(frame)
    blank_columns = [column for column in frame.columns if not populated[column].any()]
    frame = frame.drop(columns=blank_columns).reset_index(drop=True)
    frame.attrs["ingestion_audit"] = {
        "original_column_count": len(headers),
        "retained_column_count": len(frame.columns),
        "blank_columns_removed": blank_columns,
        "duplicate_headers_renamed": duplicate_renames,
        "repeated_header_rows_removed": repeated_header_rows_removed,
        "blank_rows_removed": blank_rows_removed,
    }
    return frame


def filter_qb_subtotal_rows(
    frame: pd.DataFrame,
    mapping: dict[str, Optional[str]],
) -> tuple[pd.DataFrame, int]:
    """Remove quantity/amount-only QuickBooks subtotal rows.

    QuickBooks product exports can repeat product totals beneath the actual
    transaction detail. A row is excluded only when all of the first six
    non-quantity/non-amount columns are blank, at least one mapped numeric
    field is populated, and every other source field is blank. This narrow
    rule avoids suppressing legitimate transactions with sparse references.
    """
    if frame.empty:
        return frame.copy(), 0

    numeric_columns = {
        column for column in (mapping.get("quantity"), mapping.get("amount"))
        if column in frame.columns
    }
    if not numeric_columns:
        return frame.copy(), 0

    leading_columns = [column for column in list(frame.columns)[:6] if column not in numeric_columns]
    other_columns = [column for column in frame.columns if column not in numeric_columns]
    populated = _substantive_cells(frame)
    leading_blank = ~populated[leading_columns].any(axis=1) if leading_columns else pd.Series(True, index=frame.index)
    numeric_present = populated[list(numeric_columns)].any(axis=1)
    other_blank = ~populated[other_columns].any(axis=1) if other_columns else pd.Series(True, index=frame.index)
    mask = (leading_blank & numeric_present & other_blank).astype(bool)
    filtered = frame.loc[~mask].reset_index(drop=True)
    filtered.attrs.update(frame.attrs)
    return filtered, int(mask.sum())


def infer_column(columns: list[str], patterns: list[str], optional: bool = False) -> Optional[str]:
    normalized = {col: re.sub(r"[^A-Z0-9]", "", str(col).upper()) for col in columns}
    for pattern in patterns:
        target = re.sub(r"[^A-Z0-9]", "", pattern.upper())
        for column, cleaned in normalized.items():
            if cleaned == target:
                return column
    for pattern in patterns:
        target = re.sub(r"[^A-Z0-9]", "", pattern.upper())
        for column, cleaned in normalized.items():
            # Short tokens such as NUM, PO, and PD are exact-only because
            # substring matching could map NUM to P.O. NUMBER or PO to PRODUCT.
            if len(target) >= 4 and target in cleaned:
                return column
    # Never silently map a required accounting field to an unrelated first
    # column. A missing standard field must be selected deliberately.
    return None


def select_column(label: str, columns: list[str], patterns: list[str], key: str,
                  optional: bool = False, default_column: Optional[str] = None) -> Optional[str]:
    inferred = default_column if default_column in columns else infer_column(columns, patterns, optional=optional)
    prefix = [NONE_OPTION] if optional else ([SELECT_OPTION] if inferred is None else [])
    options = prefix + columns
    default_value = inferred if inferred in options else (NONE_OPTION if optional else SELECT_OPTION)
    selected = st.selectbox(label, options, index=options.index(default_value), key=key)
    return None if selected in {NONE_OPTION, SELECT_OPTION} else selected


def build_source_validation_report(
    frame: pd.DataFrame,
    mapping: dict[str, Optional[str]],
    source: str,
    audit: Optional[dict[str, Any]] = None,
) -> pd.DataFrame:
    """Return formal pre-match validation checks for one source dataset."""
    dataset = "QuickBooks" if source == "QB" else "Infinium"
    records: list[dict[str, Any]] = []

    def add(check: str, status: str, details: str) -> None:
        records.append({"Dataset": dataset, "Check": check, "Status": status, "Details": details})

    audit = audit or {}
    if frame.empty:
        add("Usable data rows", "FAIL", "No transaction rows remain after import cleanup.")
        return pd.DataFrame(records)
    add("Usable data rows", "PASS", f"{len(frame):,} transaction row(s) available for validation.")

    required_fields = ("po", "invoice", "amount")
    missing_mappings = [field for field in required_fields if not mapping.get(field)]
    if missing_mappings:
        add(
            "Required mappings", "FAIL",
            "Missing mapping(s): " + ", ".join(missing_mappings) + ".",
        )
        return pd.DataFrame(records)

    mapped_columns = [str(mapping[field]) for field in required_fields]
    absent_columns = [column for column in mapped_columns if column not in frame.columns]
    add(
        "Mapped columns exist",
        "FAIL" if absent_columns else "PASS",
        "Missing mapped column(s): " + ", ".join(absent_columns)
        if absent_columns else "All required mapped columns are present.",
    )
    if absent_columns:
        return pd.DataFrame(records)

    duplicate_mappings = sorted({column for column in mapped_columns if mapped_columns.count(column) > 1})
    add(
        "Distinct mapping fields",
        "FAIL" if duplicate_mappings else "PASS",
        "The same source column cannot serve multiple required fields: " + ", ".join(duplicate_mappings)
        if duplicate_mappings else "PO, invoice, and amount use distinct source columns.",
    )

    amount_column = str(mapping["amount"])
    parsed_amounts = frame[amount_column].map(parse_amount_cents)
    valid_amounts = parsed_amounts.notna()
    valid_amount_count = int(valid_amounts.sum())
    valid_amount_rate = valid_amount_count / len(frame)
    if valid_amount_count == 0 or valid_amount_rate < 0.50:
        amount_status = "FAIL"
    elif valid_amount_rate < 0.90:
        amount_status = "WARNING"
    else:
        amount_status = "PASS"
    add(
        "Amount field parseability",
        amount_status,
        f"{valid_amount_count:,} of {len(frame):,} row(s) ({valid_amount_rate:.1%}) contain valid signed-cent amounts. "
        "At least 50% is required to proceed.",
    )

    po_values = frame[str(mapping["po"])].map(clean_po)
    invoice_values = frame[str(mapping["invoice"])].map(clean_alphanumeric)
    usable_references = po_values.ne("") | invoice_values.ne("")
    usable_reference_count = int(usable_references.sum())
    reference_rate = usable_reference_count / len(frame)
    reference_status = "FAIL" if usable_reference_count == 0 else ("WARNING" if reference_rate < 0.50 else "PASS")
    add(
        "Reference availability",
        reference_status,
        f"{usable_reference_count:,} of {len(frame):,} row(s) ({reference_rate:.1%}) contain a usable PO or invoice reference.",
    )

    blank_columns = list(audit.get("blank_columns_removed", []))
    add(
        "Blank-column cleanup", "PASS",
        f"Ignored {len(blank_columns):,} entirely blank column(s)."
        if blank_columns else "No entirely blank columns required removal.",
    )
    repeated_headers = int(audit.get("repeated_header_rows_removed", 0) or 0)
    add(
        "Repeated header-row cleanup", "PASS",
        f"Ignored {repeated_headers:,} repeated header row(s) found inside the data."
        if repeated_headers else "No repeated header rows were found inside the data.",
    )
    duplicate_headers = list(audit.get("duplicate_headers_renamed", []))
    add(
        "Duplicate column headers",
        "WARNING" if duplicate_headers else "PASS",
        "Preserved duplicate header(s) with unique display names: " + "; ".join(duplicate_headers)
        if duplicate_headers else "Column headers are unique.",
    )
    return pd.DataFrame(records)


def prepare_working_frame(
    raw: pd.DataFrame,
    mapping: dict[str, Optional[str]],
    source: str,
    fiscal_year: int,
) -> pd.DataFrame:
    frame = raw.copy().reset_index(drop=True)
    frame[SOURCE_POS] = range(len(frame))
    id_column = QB_ID if source == "QB" else INF_ID
    frame[id_column] = [f"{source}-{row + 1:06d}" for row in range(len(frame))]
    frame[NORM_PO] = frame[mapping["po"]].map(clean_po)
    frame[NORM_INV] = frame[mapping["invoice"]].map(clean_alphanumeric)
    frame[AMOUNT_CENTS] = frame[mapping["amount"]].map(parse_amount_cents)
    if source == "QB":
        product_col = mapping.get("product")
        period_col = mapping.get("period")
        frame[PRODUCT_STANDARD] = frame[product_col].map(product_match) if product_col else None
        if period_col:
            frame[FISCAL_LABEL] = frame[period_col].map(lambda value: fiscal_label(value, fiscal_year))
        else:
            frame[FISCAL_LABEL] = "Unspecified"
    return frame


def perform_matching(
    qb: pd.DataFrame,
    inf: pd.DataFrame,
) -> tuple[list[MatchGroup], list[int], list[int], pd.DataFrame]:
    """Perform strict one-to-one matching with vectorized uniqueness joins."""
    remaining_q = set(qb.index)
    remaining_i = set(inf.index)
    matches: list[MatchGroup] = []

    passes = [
        ((NORM_PO, NORM_INV, AMOUNT_CENTS), "PO + Invoice + Amount", "Strong",
         "Unique normalized PO, invoice, and signed amount agree."),
        ((NORM_PO, AMOUNT_CENTS), "PO + Amount", "Moderate",
         "Unique normalized PO and signed amount agree."),
        ((NORM_INV, AMOUNT_CENTS), "Invoice + Amount", "Moderate",
         "Unique normalized invoice and signed amount agree."),
    ]

    def unique_rows(
        frame: pd.DataFrame,
        remaining: set[int],
        fields: tuple[str, ...],
        index_column: str,
    ) -> pd.DataFrame:
        if not remaining:
            return pd.DataFrame(columns=[*fields, index_column])
        subset = frame.loc[sorted(remaining), list(fields)].copy()
        valid = subset.notna().all(axis=1) & subset.ne("").all(axis=1)
        subset = subset.loc[valid]
        subset[index_column] = subset.index
        return subset.drop_duplicates(subset=list(fields), keep=False)

    for fields, method, confidence, explanation in passes:
        q_unique = unique_rows(qb, remaining_q, fields, "__QB_INDEX")
        i_unique = unique_rows(inf, remaining_i, fields, "__INF_INDEX")
        if q_unique.empty or i_unique.empty:
            continue
        pairs = q_unique.merge(
            i_unique,
            on=list(fields),
            how="inner",
            sort=False,
            validate="one_to_one",
        ).sort_values("__QB_INDEX")
        pair_indexes = list(
            pairs[["__QB_INDEX", "__INF_INDEX"]].itertuples(index=False, name=None)
        )
        matches.extend(
            MatchGroup([int(qidx)], [int(iidx)], method, confidence, explanation)
            for qidx, iidx in pair_indexes
        )
        remaining_q.difference_update(int(qidx) for qidx, _ in pair_indexes)
        remaining_i.difference_update(int(iidx) for _, iidx in pair_indexes)

    matches.sort(key=lambda group: min(group.qb_rows) if group.qb_rows else 10**12)
    for number, group in enumerate(matches, 1):
        group.match_id = f"M-{number:06d}"

    candidate_columns = [
        "QuickBooks Row ID", "Disposition", "Total Candidate Count",
        "Available Candidate Count", "Available Infinium Candidate IDs",
        "Already-Matched Candidate IDs", "Minimum Amount Difference",
    ]
    q_rows = sorted(remaining_q)
    if not q_rows:
        candidates = pd.DataFrame(columns=candidate_columns)
        return matches, q_rows, sorted(remaining_i), candidates

    inf_reference = inf[[INF_ID, NORM_PO, NORM_INV, AMOUNT_CENTS]].copy()
    inf_reference["__IIDX"] = inf_reference.index

    def reference_groups(field: str) -> dict[str, list[int]]:
        populated = inf_reference.loc[inf_reference[field].ne("")]
        if populated.empty:
            return {}
        return populated.groupby(field, sort=False)["__IIDX"].agg(list).to_dict()

    po_groups = reference_groups(NORM_PO)
    invoice_groups = reference_groups(NORM_INV)

    def format_candidate_ids(indexes: list[int]) -> str:
        display_limit = 25
        displayed = [str(inf.at[idx, INF_ID]) for idx in indexes[:display_limit]]
        if len(indexes) > display_limit:
            displayed.append(f"... ({len(indexes) - display_limit} more)")
        return "; ".join(displayed)

    candidate_records: list[dict[str, Any]] = []
    for qidx in q_rows:
        candidate_indexes = set(po_groups.get(qb.at[qidx, NORM_PO], [])) if qb.at[qidx, NORM_PO] else set()
        if qb.at[qidx, NORM_INV]:
            candidate_indexes.update(invoice_groups.get(qb.at[qidx, NORM_INV], []))
        available = sorted(candidate_indexes.intersection(remaining_i))
        used = sorted(candidate_indexes.difference(remaining_i))
        qamount = qb.at[qidx, AMOUNT_CENTS]
        differences = [
            abs(int(qamount) - int(inf.at[iidx, AMOUNT_CENTS]))
            for iidx in available
            if valid_cents(qamount) and valid_cents(inf.at[iidx, AMOUNT_CENTS])
        ]
        minimum_difference = min(differences) if differences else None
        if not valid_cents(qamount):
            reason = "Invalid or missing QuickBooks amount"
        elif len(available) > 1:
            reason = "Duplicate or ambiguous Infinium values - multiple candidates"
        elif len(available) == 1 and minimum_difference == 0:
            reason = "Duplicate or ambiguous values - exact candidate is not uniquely one-to-one"
        elif len(available) == 1 and minimum_difference is not None:
            reason = "Data entry error - reference agrees but amount differs"
        elif len(available) == 1:
            reason = "Reference candidate has an invalid or missing amount"
        elif used:
            reason = "Potential duplicate - referenced Infinium candidate is already matched"
        else:
            reason = "No matching Infinium records"
        candidate_records.append(
            {
                "QuickBooks Row ID": qb.at[qidx, QB_ID],
                "Disposition": reason,
                "Total Candidate Count": len(candidate_indexes),
                "Available Candidate Count": len(available),
                "Available Infinium Candidate IDs": format_candidate_ids(available),
                "Already-Matched Candidate IDs": format_candidate_ids(used),
                "Minimum Amount Difference": cents_to_float(minimum_difference)
                if minimum_difference is not None else None,
            }
        )
    candidates = pd.DataFrame(candidate_records, columns=candidate_columns)
    return matches, sorted(remaining_q), sorted(remaining_i), candidates


def build_duplicate_analysis(
    qb: pd.DataFrame,
    inf: pd.DataFrame,
    matches: list[MatchGroup],
) -> pd.DataFrame:
    """Identify repeated accounting match keys in either source dataset."""
    matched_qb = {idx for group in matches for idx in group.qb_rows}
    matched_inf = {idx for group in matches for idx in group.inf_rows}
    key_definitions = [
        ((NORM_PO, NORM_INV, AMOUNT_CENTS), "PO + Invoice + Amount"),
        ((NORM_PO, AMOUNT_CENTS), "PO + Amount"),
        ((NORM_INV, AMOUNT_CENTS), "Invoice + Amount"),
    ]
    records: list[dict[str, Any]] = []
    for dataset, frame, id_column, matched_rows in (
        ("QuickBooks", qb, QB_ID, matched_qb),
        ("Infinium", inf, INF_ID, matched_inf),
    ):
        for fields, key_type in key_definitions:
            work = frame.loc[:, list(fields)].copy()
            valid = work.notna().all(axis=1) & work.ne("").all(axis=1)
            work = work.loc[valid]
            if work.empty:
                continue
            work["__SOURCE_ID"] = frame.loc[work.index, id_column].astype(str)
            work["__MATCHED"] = work.index.isin(matched_rows)
            work = work.loc[work.duplicated(subset=list(fields), keep=False)]
            if work.empty:
                continue
            grouped = work.groupby(list(fields), sort=True, dropna=False).agg(
                occurrence_count=("__SOURCE_ID", "size"),
                source_row_ids=("__SOURCE_ID", lambda values: "; ".join(values)),
                matched_count=("__MATCHED", "sum"),
            ).reset_index()
            for row in grouped.to_dict("records"):
                occurrence_count = int(row["occurrence_count"])
                matched_count = int(row["matched_count"])
                if matched_count == occurrence_count:
                    status = "All rows matched through a more specific unique key"
                elif matched_count:
                    status = "Mixed matched and unresolved rows"
                else:
                    status = "All rows unresolved"
                records.append(
                    {
                        "Dataset": dataset,
                        "Duplicate Key Type": key_type,
                        "Normalized PO": row.get(NORM_PO, ""),
                        "Normalized Invoice": row.get(NORM_INV, ""),
                        "Amount": cents_to_float(row[AMOUNT_CENTS]),
                        "Occurrence Count": occurrence_count,
                        "Source Row IDs": row["source_row_ids"],
                        "Reconciliation Status": status,
                    }
                )
    columns = [
        "Dataset", "Duplicate Key Type", "Normalized PO", "Normalized Invoice",
        "Amount", "Occurrence Count", "Source Row IDs", "Reconciliation Status",
    ]
    return pd.DataFrame(records, columns=columns)


def build_paired_rows(
    matches: list[MatchGroup],
    unmatched_qb: list[int],
    unmatched_inf: list[int],
    qb: pd.DataFrame,
    inf: pd.DataFrame,
    candidates: pd.DataFrame,
) -> list[dict[str, Any]]:
    rows: list[dict[str, Any]] = []
    candidate_reason = (
        candidates.set_index("QuickBooks Row ID")["Disposition"].to_dict()
        if not candidates.empty else {}
    )
    for group in matches:
        ordered_q = sorted(group.qb_rows, key=lambda idx: qb.at[idx, SOURCE_POS])
        ordered_i = sorted(group.inf_rows, key=lambda idx: inf.at[idx, SOURCE_POS])
        for sequence, (qidx, iidx) in enumerate(zip_longest(ordered_q, ordered_i), 1):
            result_label = group.method
            if group.group_level:
                result_label += " [group-level; no line allocation]"
            rows.append(
                {
                    "Section": "01 Matched",
                    "Match ID": group.match_id,
                    "Match Result": result_label,
                    "QB Index": qidx,
                    "Infinium Index": iidx,
                    "Group Sequence": sequence,
                    "Confidence": group.confidence,
                    "Explanation": group.explanation,
                }
            )
    for qidx in unmatched_qb:
        qb_id = qb.at[qidx, QB_ID]
        rows.append(
            {
                "Section": "02 Unmatched QuickBooks",
                "Match ID": "",
                "Match Result": candidate_reason.get(qb_id, "Unmatched QuickBooks"),
                "QB Index": qidx,
                "Infinium Index": None,
                "Group Sequence": None,
                "Confidence": "Review",
                "Explanation": "No unique automatic Infinium match was established.",
            }
        )
    for iidx in unmatched_inf:
        rows.append(
            {
                "Section": "03 Unmatched Infinium",
                "Match ID": "",
                "Match Result": "Unmatched Infinium",
                "QB Index": None,
                "Infinium Index": iidx,
                "Group Sequence": None,
                "Confidence": "Review",
                "Explanation": "No unique automatic QuickBooks match was established.",
            }
        )
    return rows


def build_normalization_detail(
    qb: pd.DataFrame,
    inf: pd.DataFrame,
    qb_mapping: dict[str, Optional[str]],
    inf_mapping: dict[str, Optional[str]],
) -> pd.DataFrame:
    records: list[dict[str, Any]] = []
    for source, frame, mapping, id_col in (
        ("QuickBooks", qb, qb_mapping, QB_ID),
        ("Infinium", inf, inf_mapping, INF_ID),
    ):
        for idx, row in frame.iterrows():
            record = {
                "Dataset": source,
                "Source Row ID": row[id_col],
                "Original PO": row[mapping["po"]],
                "Normalized PO": row[NORM_PO],
                "Original Invoice": row[mapping["invoice"]],
                "Normalized Invoice": row[NORM_INV],
                "Original Amount": row[mapping["amount"]],
                "Normalized Amount": cents_to_float(row[AMOUNT_CENTS])
                if valid_cents(row[AMOUNT_CENTS]) else None,
                "Amount Valid": valid_cents(row[AMOUNT_CENTS]),
            }
            if source == "QuickBooks":
                product_col = mapping.get("product")
                period_col = mapping.get("period")
                record.update(
                    {
                        "Original Product Description": row[product_col] if product_col else None,
                        "Standardized Product": row[PRODUCT_STANDARD],
                        "Original Fiscal Period": row[period_col] if period_col else None,
                        "Fiscal Period Label": row[FISCAL_LABEL],
                    }
                )
            records.append(record)
    return pd.DataFrame(records)


def build_match_assessments(
    matches: list[MatchGroup],
    unmatched_qb: list[int],
    qb: pd.DataFrame,
    inf: pd.DataFrame,
    candidates: pd.DataFrame,
) -> pd.DataFrame:
    records: list[dict[str, Any]] = []
    candidate_map = candidates.set_index("QuickBooks Row ID").to_dict("index") if not candidates.empty else {}
    for group in matches:
        q_po = {qb.at[idx, NORM_PO] for idx in group.qb_rows if qb.at[idx, NORM_PO]}
        i_po = {inf.at[idx, NORM_PO] for idx in group.inf_rows if inf.at[idx, NORM_PO]}
        q_inv = {qb.at[idx, NORM_INV] for idx in group.qb_rows if qb.at[idx, NORM_INV]}
        i_inv = {inf.at[idx, NORM_INV] for idx in group.inf_rows if inf.at[idx, NORM_INV]}
        q_total = sum(cents_or_zero(qb.at[idx, AMOUNT_CENTS]) for idx in group.qb_rows)
        i_total = sum(cents_or_zero(inf.at[idx, AMOUNT_CENTS]) for idx in group.inf_rows)
        records.append(
            {
                "Match ID": group.match_id,
                "Decision": "Matched",
                "Match Method": group.method,
                "Confidence": group.confidence,
                "QuickBooks Row Count": len(group.qb_rows),
                "Infinium Row Count": len(group.inf_rows),
                "QuickBooks Row IDs": "; ".join(qb.at[idx, QB_ID] for idx in group.qb_rows),
                "Infinium Row IDs": "; ".join(inf.at[idx, INF_ID] for idx in group.inf_rows),
                "PO Criterion": "Agree" if q_po and q_po == i_po else "Not used / differs",
                "Invoice Criterion": "Agree" if q_inv and q_inv == i_inv else "Not used / differs",
                "Signed Amount Criterion": "Agree" if q_total == i_total else "Differs",
                "QuickBooks Amount": cents_to_float(q_total),
                "Infinium Amount": cents_to_float(i_total),
                "Amount Difference": cents_to_float(q_total - i_total),
                "Group-Level Match": group.group_level,
                "Assessment Explanation": group.explanation,
            }
        )
    for qidx in unmatched_qb:
        qid = qb.at[qidx, QB_ID]
        candidate = candidate_map.get(qid, {})
        records.append(
            {
                "Match ID": "",
                "Decision": "Unresolved",
                "Match Method": candidate.get("Disposition", "No match"),
                "Confidence": "Review",
                "QuickBooks Row Count": 1,
                "Infinium Row Count": candidate.get("Available Candidate Count", 0),
                "QuickBooks Row IDs": qid,
                "Infinium Row IDs": candidate.get("Available Infinium Candidate IDs", ""),
                "PO Criterion": "Candidate search performed" if qb.at[qidx, NORM_PO] else "Missing",
                "Invoice Criterion": "Candidate search performed" if qb.at[qidx, NORM_INV] else "Missing",
                "Signed Amount Criterion": "Valid" if valid_cents(qb.at[qidx, AMOUNT_CENTS]) else "Invalid / missing",
                "QuickBooks Amount": cents_to_float(qb.at[qidx, AMOUNT_CENTS]),
                "Infinium Amount": None,
                "Amount Difference": candidate.get("Minimum Amount Difference"),
                "Group-Level Match": False,
                "Assessment Explanation": "No unique automatic match was found.",
            }
        )
    return pd.DataFrame(records)


def build_method_summary(
    matches: list[MatchGroup],
    unmatched_qb: list[int],
    unmatched_inf: list[int],
    qb: pd.DataFrame,
    inf: pd.DataFrame,
) -> pd.DataFrame:
    buckets: dict[str, dict[str, Any]] = defaultdict(
        lambda: {"QB Rows": 0, "Infinium Rows": 0, "QB Cents": 0, "Infinium Cents": 0}
    )
    for group in matches:
        bucket = buckets[group.method]
        bucket["QB Rows"] += len(group.qb_rows)
        bucket["Infinium Rows"] += len(group.inf_rows)
        bucket["QB Cents"] += sum(cents_or_zero(qb.at[idx, AMOUNT_CENTS]) for idx in group.qb_rows)
        bucket["Infinium Cents"] += sum(cents_or_zero(inf.at[idx, AMOUNT_CENTS]) for idx in group.inf_rows)
    if unmatched_qb:
        bucket = buckets["Unmatched QuickBooks"]
        bucket["QB Rows"] = len(unmatched_qb)
        bucket["QB Cents"] = sum(cents_or_zero(qb.at[idx, AMOUNT_CENTS]) for idx in unmatched_qb)
    if unmatched_inf:
        bucket = buckets["Unmatched Infinium"]
        bucket["Infinium Rows"] = len(unmatched_inf)
        bucket["Infinium Cents"] = sum(cents_or_zero(inf.at[idx, AMOUNT_CENTS]) for idx in unmatched_inf)
    records = []
    for method, values in buckets.items():
        records.append(
            {
                "Match Method": method,
                "QuickBooks Rows": values["QB Rows"],
                "Infinium Rows": values["Infinium Rows"],
                "QuickBooks Amount": cents_to_float(values["QB Cents"]),
                "Infinium Amount": cents_to_float(values["Infinium Cents"]),
                "Amount Difference": cents_to_float(values["QB Cents"] - values["Infinium Cents"]),
                "Share of QuickBooks Rows": values["QB Rows"] / len(qb) if len(qb) else 0,
            }
        )
    return pd.DataFrame(records).sort_values(
        ["QuickBooks Rows", "Infinium Rows", "Match Method"], ascending=[False, False, True]
    ).reset_index(drop=True)


def build_product_summary(qb: pd.DataFrame, mapping: dict[str, Optional[str]]) -> pd.DataFrame:
    qty_col = mapping.get("quantity")
    amount_col = mapping.get("amount")
    if not qty_col or not amount_col:
        return pd.DataFrame(columns=["Product Name", "Product Quantity", "Product Value"])
    work = qb[qb[PRODUCT_STANDARD].notna()].copy()
    if work.empty:
        return pd.DataFrame(columns=["Product Name", "Product Quantity", "Product Value"])
    work["__QTY"] = pd.to_numeric(work[qty_col], errors="coerce").fillna(0)
    work["__AMOUNT"] = work[AMOUNT_CENTS].map(cents_to_float)
    return (
        work.groupby(PRODUCT_STANDARD, as_index=False)
        .agg(**{"Product Quantity": ("__QTY", "sum"), "Product Value": ("__AMOUNT", "sum")})
        .rename(columns={PRODUCT_STANDARD: "Product Name"})
        .sort_values("Product Name")
        .reset_index(drop=True)
    )


def _period_sort(label: str) -> tuple[int, int, str]:
    match = re.fullmatch(r"P(\d{2})-(\d{4})", str(label))
    if not match:
        return 9999, 99, str(label)
    return int(match.group(2)), int(match.group(1)), str(label)


def build_exception_analysis(
    qb: pd.DataFrame,
    inf: pd.DataFrame,
    unmatched_qb: list[int],
    unmatched_inf: list[int],
    candidates: pd.DataFrame,
) -> pd.DataFrame:
    records: list[dict[str, Any]] = []
    candidate_reason = candidates.set_index("QuickBooks Row ID")["Disposition"].to_dict() if not candidates.empty else {}
    period_values = qb.loc[unmatched_qb, FISCAL_LABEL] if unmatched_qb else pd.Series(dtype=object)
    has_period = not period_values.empty and period_values.ne("Unspecified").any()
    period_groups: dict[str, list[int]] = defaultdict(list)
    for idx in unmatched_qb:
        label = qb.at[idx, FISCAL_LABEL] if has_period else "All QuickBooks transactions"
        period_groups[label].append(idx)
    for label in sorted(period_groups, key=_period_sort):
        rows = period_groups[label]
        records.append(
            {
                "Analysis Type": "QuickBooks exceptions by source period",
                "Dimension": label,
                "Transaction Count": len(rows),
                "Amount": cents_to_float(sum(cents_or_zero(qb.at[idx, AMOUNT_CENTS]) for idx in rows)),
            }
        )
    reason_groups: dict[str, list[int]] = defaultdict(list)
    for idx in unmatched_qb:
        reason_groups[candidate_reason.get(qb.at[idx, QB_ID], "No match")].append(idx)
    for reason, rows in sorted(reason_groups.items()):
        records.append(
            {
                "Analysis Type": "QuickBooks exceptions by reason",
                "Dimension": reason,
                "Transaction Count": len(rows),
                "Amount": cents_to_float(sum(cents_or_zero(qb.at[idx, AMOUNT_CENTS]) for idx in rows)),
            }
        )
    if unmatched_inf:
        records.append(
            {
                "Analysis Type": "Infinium exceptions",
                "Dimension": "Unmatched Infinium",
                "Transaction Count": len(unmatched_inf),
                "Amount": cents_to_float(sum(cents_or_zero(inf.at[idx, AMOUNT_CENTS]) for idx in unmatched_inf)),
            }
        )
    return pd.DataFrame(records)


def build_rules_and_config(
    qb_mapping: dict[str, Optional[str]],
    inf_mapping: dict[str, Optional[str]],
    metadata: dict[str, Any],
) -> tuple[pd.DataFrame, pd.DataFrame]:
    rules = pd.DataFrame(
        [
            {"Priority": 1, "Rule": "PO + Invoice + Amount", "Automatic": "Yes",
             "Requirement": "One unique row per dataset; normalized references and exact signed cents agree."},
            {"Priority": 2, "Rule": "PO + Amount", "Automatic": "Yes",
             "Requirement": "One unique remaining row per dataset; normalized PO and exact signed cents agree."},
            {"Priority": 3, "Rule": "Invoice + Amount", "Automatic": "Yes",
             "Requirement": "One unique remaining row per dataset; normalized invoice and exact signed cents agree."},
            {"Priority": 4, "Rule": "Grouped transactions", "Automatic": "No",
             "Requirement": "One-to-many, many-to-one, and many-to-many relationships remain unresolved."},
            {"Priority": 5, "Rule": "Amount variance", "Automatic": "No",
             "Requirement": "Any nonzero cent difference is flagged as an exception; no tolerance is applied."},
            {"Priority": 6, "Rule": "Fuzzy product classification", "Automatic": "No financial effect",
             "Requirement": "Used only for Product Aggregate Summary; never determines transaction matching."},
        ]
    )
    config_records = [
        {"Setting": "Application Version", "Value": APP_VERSION},
        {"Setting": "Matching Rule Version", "Value": MATCHING_RULE_VERSION},
        {"Setting": "Run ID", "Value": metadata["run_id"]},
        {"Setting": "Run Timestamp (Central Time)", "Value": metadata["run_timestamp"]},
        {"Setting": "QuickBooks Filename", "Value": metadata["qb_filename"]},
        {"Setting": "QuickBooks SHA-256", "Value": metadata["qb_sha256"]},
        {"Setting": "Infinium Filename", "Value": metadata["inf_filename"]},
        {"Setting": "Infinium SHA-256", "Value": metadata["inf_sha256"]},
        {"Setting": "Automatic Amount Tolerance", "Value": "$0.00; automatic matches require exact signed cents"},
        {"Setting": "Match Cardinality", "Value": "Strict one-to-one only"},
        {"Setting": "Selected Fiscal Year", "Value": metadata["fiscal_year"]},
        {"Setting": "Selected Fiscal Period", "Value": metadata["fiscal_period"]},
        {"Setting": "QuickBooks subtotal rows excluded", "Value": metadata.get("qb_subtotal_rows_excluded", 0)},
        {"Setting": "Source validation warnings", "Value": metadata.get("source_validation_warnings", 0)},
        {
            "Setting": "Fiscal Period Treatment",
            "Value": (
                "Selected period is classified as current; all other valid periods are urgent prior-period exceptions "
                "exceptions. Fiscal period never changes strict matching."
            ),
        },
    ]
    for source_name, audit_key in (
        ("QuickBooks", "qb_import_audit"),
        ("Infinium", "inf_import_audit"),
    ):
        audit = metadata.get(audit_key, {}) or {}
        config_records.extend(
            [
                {
                    "Setting": f"{source_name} blank columns removed",
                    "Value": len(audit.get("blank_columns_removed", [])),
                },
                {
                    "Setting": f"{source_name} repeated header rows removed",
                    "Value": int(audit.get("repeated_header_rows_removed", 0) or 0),
                },
                {
                    "Setting": f"{source_name} duplicate headers renamed",
                    "Value": len(audit.get("duplicate_headers_renamed", [])),
                },
            ]
        )
    for source, mapping in (("QuickBooks", qb_mapping), ("Infinium", inf_mapping)):
        for field_name, column_name in mapping.items():
            config_records.append(
                {"Setting": f"{source} mapping - {field_name}", "Value": column_name or "Not mapped"}
            )
    return rules, pd.DataFrame(config_records)


def build_controls(
    qb: pd.DataFrame,
    inf: pd.DataFrame,
    matches: list[MatchGroup],
    unmatched_qb: list[int],
    unmatched_inf: list[int],
) -> pd.DataFrame:
    matched_q = sorted({idx for group in matches for idx in group.qb_rows})
    matched_i = sorted({idx for group in matches for idx in group.inf_rows})
    qb_total = sum(cents_or_zero(qb.at[idx, AMOUNT_CENTS]) for idx in qb.index)
    inf_total = sum(cents_or_zero(inf.at[idx, AMOUNT_CENTS]) for idx in inf.index)
    matched_q_total = sum(cents_or_zero(qb.at[idx, AMOUNT_CENTS]) for idx in matched_q)
    matched_i_total = sum(cents_or_zero(inf.at[idx, AMOUNT_CENTS]) for idx in matched_i)
    unresolved_q_total = sum(cents_or_zero(qb.at[idx, AMOUNT_CENTS]) for idx in unmatched_qb)
    records = [
        ("QuickBooks row completeness", len(qb), len(matched_q) + len(unmatched_qb)),
        ("Infinium row completeness", len(inf), len(matched_i) + len(unmatched_inf)),
        ("QuickBooks amount roll-forward", cents_to_float(qb_total),
         cents_to_float(matched_q_total + unresolved_q_total)),
        ("Matched ledger totals", cents_to_float(matched_q_total), cents_to_float(matched_i_total)),
        ("Unresolved JE support", cents_to_float(unresolved_q_total),
         cents_to_float(qb_total - matched_q_total)),
    ]
    output = []
    for check, expected, actual in records:
        difference = float(expected) - float(actual)
        output.append(
            {
                "Check": check,
                "Expected": expected,
                "Actual": actual,
                "Difference": difference,
                "Status": "PASS" if difference == 0 else "FAIL",
            }
        )
    return pd.DataFrame(output)


def build_reconciliation(
    qb_raw: pd.DataFrame,
    inf_raw: pd.DataFrame,
    qb_mapping: dict[str, Optional[str]],
    inf_mapping: dict[str, Optional[str]],
    metadata: dict[str, Any],
    fiscal_year: int,
) -> ReconciliationResult:
    qb = prepare_working_frame(qb_raw, qb_mapping, "QB", fiscal_year)
    inf = prepare_working_frame(inf_raw, inf_mapping, "INF", fiscal_year)
    matches, unmatched_qb, unmatched_inf, candidates = perform_matching(qb, inf)
    paired_rows = build_paired_rows(matches, unmatched_qb, unmatched_inf, qb, inf, candidates)
    normalization = build_normalization_detail(qb, inf, qb_mapping, inf_mapping)
    assessments = build_match_assessments(matches, unmatched_qb, qb, inf, candidates)
    method_summary = build_method_summary(matches, unmatched_qb, unmatched_inf, qb, inf)
    exception_analysis = build_exception_analysis(qb, inf, unmatched_qb, unmatched_inf, candidates)
    duplicate_analysis = build_duplicate_analysis(qb, inf, matches)
    product_summary = build_product_summary(qb, qb_mapping)
    controls = build_controls(qb, inf, matches, unmatched_qb, unmatched_inf)
    rules, config = build_rules_and_config(qb_mapping, inf_mapping, metadata)

    matched_q = sorted({idx for group in matches for idx in group.qb_rows})
    matched_i = sorted({idx for group in matches for idx in group.inf_rows})
    qb_total_cents = sum(cents_or_zero(qb.at[idx, AMOUNT_CENTS]) for idx in qb.index)
    inf_total_cents = sum(cents_or_zero(inf.at[idx, AMOUNT_CENTS]) for idx in inf.index)
    unmatched_q_cents = sum(cents_or_zero(qb.at[idx, AMOUNT_CENTS]) for idx in unmatched_qb)
    matched_q_cents = sum(cents_or_zero(qb.at[idx, AMOUNT_CENTS]) for idx in matched_q)
    matched_i_cents = sum(cents_or_zero(inf.at[idx, AMOUNT_CENTS]) for idx in matched_i)
    qb_gross = sum(abs(cents_or_zero(qb.at[idx, AMOUNT_CENTS])) for idx in qb.index)
    matched_q_gross = sum(abs(cents_or_zero(qb.at[idx, AMOUNT_CENTS])) for idx in matched_q)
    metrics = {
        "QuickBooks Rows": len(qb),
        "Infinium Rows": len(inf),
        "QuickBooks Source Total": cents_to_float(qb_total_cents),
        "Infinium Source Total": cents_to_float(inf_total_cents),
        "Source Difference": cents_to_float(qb_total_cents - inf_total_cents),
        "Matched QuickBooks Rows": len(matched_q),
        "Matched Infinium Rows": len(matched_i),
        "Matched QuickBooks Amount": cents_to_float(matched_q_cents),
        "Matched Infinium Amount": cents_to_float(matched_i_cents),
        "Matched Amount Difference": cents_to_float(matched_q_cents - matched_i_cents),
        "Unresolved QuickBooks Rows": len(unmatched_qb),
        "Unresolved QuickBooks Amount": cents_to_float(unmatched_q_cents),
        "Unmatched Infinium Rows": len(unmatched_inf),
        "Unmatched Infinium Amount": cents_to_float(
            sum(cents_or_zero(inf.at[idx, AMOUNT_CENTS]) for idx in unmatched_inf)
        ),
        "QuickBooks Match Rate by Row": len(matched_q) / len(qb) if len(qb) else 0,
        "QuickBooks Match Rate by Gross Amount": matched_q_gross / qb_gross if qb_gross else 0,
        "Invalid QuickBooks Amounts": int(qb[AMOUNT_CENTS].isna().sum()),
        "Invalid Infinium Amounts": int(inf[AMOUNT_CENTS].isna().sum()),
        "QuickBooks Subtotal Rows Excluded": int(metadata.get("qb_subtotal_rows_excluded", 0)),
        "Duplicate Key Groups": len(duplicate_analysis),
        "Control Status": "PASS" if controls["Status"].eq("PASS").all() else "FAIL",
    }

    result = ReconciliationResult(
        run_id=metadata["run_id"],
        run_timestamp=metadata["run_timestamp_dt"],
        qb_raw=qb_raw.copy(),
        inf_raw=inf_raw.copy(),
        qb_work=qb,
        inf_work=inf,
        matches=matches,
        paired_rows=paired_rows,
        candidates=candidates,
        normalization=normalization,
        assessments=assessments,
        method_summary=method_summary,
        exception_analysis=exception_analysis,
        duplicate_analysis=duplicate_analysis,
        product_summary=product_summary,
        controls=controls,
        metrics=metrics,
        rules=rules,
        config=config,
        qb_mapping=qb_mapping,
        inf_mapping=inf_mapping,
        metadata=metadata,
        unmatched_qb=unmatched_qb,
        unmatched_inf=unmatched_inf,
    )
    validate_reconciliation(result)
    return result


def validate_reconciliation(result: ReconciliationResult) -> None:
    if result.controls["Status"].ne("PASS").any():
        failures = result.controls.loc[result.controls["Status"] != "PASS", "Check"].tolist()
        raise ValueError(f"Reconciliation control failure: {', '.join(failures)}")
    if any(len(group.qb_rows) != 1 or len(group.inf_rows) != 1 for group in result.matches):
        raise ValueError("Strict matching control failure: every accepted match must be one-to-one.")
    qb_occurrences = Counter(
        row["QB Index"] for row in result.paired_rows if row["QB Index"] is not None
    )
    inf_occurrences = Counter(
        row["Infinium Index"] for row in result.paired_rows if row["Infinium Index"] is not None
    )
    expected_qb = set(result.qb_work.index)
    expected_inf = set(result.inf_work.index)
    if set(qb_occurrences) != expected_qb or any(count != 1 for count in qb_occurrences.values()):
        raise ValueError("QuickBooks rows were dropped or duplicated while building the reconciled output.")
    if set(inf_occurrences) != expected_inf or any(count != 1 for count in inf_occurrences.values()):
        raise ValueError("Infinium rows were dropped or duplicated while building the reconciled output.")


# ---------------------------------------------------------------------------
# Excel construction
# ---------------------------------------------------------------------------


def _thin_border() -> Border:
    side = Side(style="thin", color=BORDER)
    return Border(left=side, right=side, top=side, bottom=side)


def _total_border() -> Border:
    return Border(
        top=Side(style="thin", color=SLATE),
        bottom=Side(style="double", color=SLATE),
    )


def _write_dataframe_values(ws, frame: pd.DataFrame, start_row: int, start_col: int) -> None:
    for col_offset, header in enumerate(frame.columns):
        ws.cell(start_row, start_col + col_offset, excel_safe(str(header)))
    for row_offset, row in enumerate(frame.itertuples(index=False, name=None), 1):
        for col_offset, value in enumerate(row):
            ws.cell(start_row + row_offset, start_col + col_offset, excel_safe(value))


def _format_header(ws, row: int, start_col: int, end_col: int, color: str) -> None:
    for col in range(start_col, end_col + 1):
        cell = ws.cell(row, col)
        cell.fill = PatternFill("solid", fgColor=color)
        cell.font = Font(name="Segoe UI", size=10, bold=True, color=WHITE)
        cell.alignment = Alignment(horizontal="left", vertical="center", wrap_text=True)
        cell.border = Border(bottom=Side(style="medium", color=color))
    ws.row_dimensions[row].height = 34


def _format_body_block(
    ws,
    start_row: int,
    end_row: int,
    start_col: int,
    end_col: int,
    light_fill: str,
) -> None:
    border = _thin_border()
    for row in range(start_row, end_row + 1):
        fill = PatternFill("solid", fgColor=light_fill) if row % 2 == 0 else PatternFill(fill_type=None)
        for col in range(start_col, end_col + 1):
            cell = ws.cell(row, col)
            cell.font = Font(name="Segoe UI", size=10, color=TEXT)
            cell.border = border
            cell.fill = fill
            cell.alignment = Alignment(horizontal="left", vertical="center")
        ws.row_dimensions[row].height = 20


def _apply_number_formats(
    ws,
    headers: list[str],
    start_row: int,
    end_row: int,
    start_col: int,
    amount_columns: set[str],
    quantity_columns: set[str],
) -> None:
    for offset, header in enumerate(headers):
        col = start_col + offset
        header_upper = str(header).upper()
        for row in range(start_row, end_row + 1):
            cell = ws.cell(row, col)
            if any(term in header_upper for term in ("VALID", "GROUP-LEVEL", "AUTOMATIC")):
                cell.alignment = Alignment(horizontal="center", vertical="center")
            elif any(term in header_upper for term in ("PERCENT", "RATE", "SHARE")):
                cell.number_format = "0.0%"
                cell.alignment = Alignment(horizontal="right", vertical="center")
            elif any(term in header_upper for term in ("COUNT", "ROWS", "CANDIDATE COUNT")):
                cell.number_format = '#,##0;[Red](#,##0);-'
                cell.alignment = Alignment(horizontal="right", vertical="center")
            elif header in amount_columns or any(term in header_upper for term in ("AMOUNT", "VALUE", "VARIANCE", "DIFFERENCE", "BALANCE", "EXPOSURE", "TOLERANCE")):
                cell.number_format = '$#,##0.00;[Red]($#,##0.00);-'
                cell.alignment = Alignment(horizontal="right", vertical="center")
            elif header in quantity_columns or any(term in header_upper for term in ("QUANTITY", "QTY", "COUNT", "ROWS")):
                cell.number_format = '#,##0.00;[Red](#,##0.00);-'
                cell.alignment = Alignment(horizontal="right", vertical="center")
            elif "DATE" in header_upper or "TIMESTAMP" in header_upper:
                cell.number_format = "yyyy-mm-dd"
                cell.alignment = Alignment(horizontal="center", vertical="center")


def _set_widths(
    ws,
    start_col: int,
    end_col: int,
    start_row: int,
    end_row: int,
    minimum: float = 11,
    maximum: float = 34,
) -> None:
    for col in range(start_col, end_col + 1):
        lengths = [len(str(ws.cell(row, col).value or "")) for row in range(start_row, end_row + 1)]
        ws.column_dimensions[get_column_letter(col)].width = min(max(max(lengths, default=0) + 2, minimum), maximum)


def _autofit_workbook_columns(wb: Workbook, minimum: float = 10, maximum: float = 52) -> None:
    """Auto-size every used worksheet column while respecting merged layout bands."""
    for ws in wb.worksheets:
        merged_coordinates: set[str] = set()
        for merged_range in ws.merged_cells.ranges:
            for row in ws.iter_rows(
                min_row=merged_range.min_row,
                max_row=merged_range.max_row,
                min_col=merged_range.min_col,
                max_col=merged_range.max_col,
            ):
                merged_coordinates.update(cell.coordinate for cell in row)

        for column_index in range(1, ws.max_column + 1):
            letter = get_column_letter(column_index)
            maximum_length = 0
            has_unmerged_value = False
            for row_index in range(1, ws.max_row + 1):
                cell = ws.cell(row_index, column_index)
                if cell.coordinate in merged_coordinates or cell.value is None:
                    continue
                has_unmerged_value = True
                value = cell.value
                if isinstance(value, datetime):
                    display = value.strftime("%Y-%m-%d %I:%M:%S %p")
                elif isinstance(value, (int, float, Decimal)) and not isinstance(value, bool):
                    if "$" in str(cell.number_format):
                        display = f"${float(value):,.2f}"
                    elif any(token in str(cell.number_format) for token in ("0.00", "#,##0")):
                        display = f"{float(value):,.2f}"
                    else:
                        display = str(value)
                else:
                    display = str(value)
                maximum_length = max(
                    maximum_length,
                    max((len(line) for line in display.splitlines()), default=0),
                )

            if has_unmerged_value:
                ws.column_dimensions[letter].width = min(max(maximum_length + 2, minimum), maximum)
            else:
                existing = ws.column_dimensions[letter].width or minimum
                ws.column_dimensions[letter].width = min(max(existing, 3.5), maximum)


def _write_title_band(ws, row: int, start_col: int, end_col: int, title: str, color: str) -> None:
    if start_col < end_col:
        ws.merge_cells(start_row=row, start_column=start_col, end_row=row, end_column=end_col)
    cell = ws.cell(row, start_col, title)
    cell.fill = PatternFill("solid", fgColor=color)
    cell.font = Font(name="Segoe UI", size=12, bold=True, color=WHITE)
    cell.alignment = Alignment(horizontal="left", vertical="center")
    for col in range(start_col + 1, end_col + 1):
        ws.cell(row, col).fill = PatternFill("solid", fgColor=color)
    ws.row_dimensions[row].height = 27


def _write_caption_band(ws, row: int, start_col: int, end_col: int, caption: str, color: str) -> None:
    if start_col < end_col:
        ws.merge_cells(start_row=row, start_column=start_col, end_row=row, end_column=end_col)
    cell = ws.cell(row, start_col, caption)
    cell.fill = PatternFill("solid", fgColor=SLATE_LIGHT)
    cell.font = Font(name="Segoe UI", size=9, italic=True, color=color)
    cell.alignment = Alignment(horizontal="left", vertical="center", wrap_text=True)
    for col in range(start_col + 1, end_col + 1):
        ws.cell(row, col).fill = PatternFill("solid", fgColor=SLATE_LIGHT)
    ws.row_dimensions[row].height = 30


def _write_total_row(
    ws,
    row: int,
    start_col: int,
    end_col: int,
    totals: dict[str, float],
    headers: list[str],
    label: str = "TOTAL",
) -> None:
    for col in range(start_col, end_col + 1):
        cell = ws.cell(row, col)
        cell.fill = PatternFill("solid", fgColor=TOTAL_FILL)
        cell.font = Font(name="Segoe UI", size=10, bold=True, color=TEXT)
        cell.border = _total_border()
    ws.cell(row, start_col, label)
    for offset, header in enumerate(headers):
        if header in totals:
            cell = ws.cell(row, start_col + offset, totals[header])
            cell.number_format = '$#,##0.00;[Red]($#,##0.00);-' if "amount" in header.lower() or "value" in header.lower() else '#,##0.00;[Red](#,##0.00);-'
            cell.alignment = Alignment(horizontal="right", vertical="center")
    ws.row_dimensions[row].height = 23


def _source_totals(frame: pd.DataFrame, mapping: dict[str, Optional[str]]) -> dict[str, float]:
    totals: dict[str, float] = {}
    amount_col = mapping.get("amount")
    quantity_col = mapping.get("quantity")
    if amount_col:
        totals[amount_col] = numeric_sum(frame[amount_col])
    if quantity_col:
        totals[quantity_col] = numeric_quantity_sum(frame[quantity_col])
    return totals


def _prepare_sheet(ws, landscape: bool = True) -> None:
    ws.sheet_view.showGridLines = False
    ws.sheet_properties.pageSetUpPr.fitToPage = True
    ws.page_setup.orientation = "landscape" if landscape else "portrait"
    ws.page_setup.paperSize = ws.PAPERSIZE_A3 if landscape else ws.PAPERSIZE_LETTER
    ws.page_setup.fitToWidth = 1
    ws.page_setup.fitToHeight = 0
    ws.sheet_properties.pageSetUpPr.autoPageBreaks = False


def build_raw_data_sheet(wb: Workbook, result: ReconciliationResult) -> None:
    ws = wb.active
    ws.title = "Raw Data"
    qb_headers = list(result.qb_raw.columns)
    inf_headers = list(result.inf_raw.columns)
    qb_start = 1
    separator_col = len(qb_headers) + 1
    inf_start = separator_col + 1
    header_row = 3
    data_row = 4
    qb_end = len(qb_headers)
    inf_end = inf_start + len(inf_headers) - 1

    _write_title_band(ws, 1, qb_start, qb_end, "QUICKBOOKS | RAW TRANSACTION DETAIL", NAVY)
    _write_title_band(ws, 1, inf_start, inf_end, "INFINIUM | RAW UPLOAD", TEAL)
    _write_caption_band(
        ws, 2, qb_start, qb_end,
        f"{len(result.qb_raw):,} rows | Source control total: ${result.metrics['QuickBooks Source Total']:,.2f} | "
        f"{result.metrics['QuickBooks Subtotal Rows Excluded']:,} subtotal row(s) excluded before matching | "
        f"Generated {format_central_timestamp(result.run_timestamp)}",
        NAVY,
    )
    _write_caption_band(
        ws, 2, inf_start, inf_end,
        f"{len(result.inf_raw):,} rows | Source control total: ${result.metrics['Infinium Source Total']:,.2f} | "
        f"Values preserved before matching | Generated {format_central_timestamp(result.run_timestamp)}",
        TEAL,
    )
    _write_dataframe_values(ws, result.qb_raw, header_row, qb_start)
    _write_dataframe_values(ws, result.inf_raw, header_row, inf_start)
    _format_header(ws, header_row, qb_start, qb_end, NAVY)
    _format_header(ws, header_row, inf_start, inf_end, TEAL)
    _format_body_block(ws, data_row, data_row + len(result.qb_raw) - 1, qb_start, qb_end, NAVY_LIGHT)
    _format_body_block(ws, data_row, data_row + len(result.inf_raw) - 1, inf_start, inf_end, TEAL_LIGHT)
    qb_total_row = data_row + len(result.qb_raw)
    inf_total_row = data_row + len(result.inf_raw)
    _write_total_row(ws, qb_total_row, qb_start, qb_end, _source_totals(result.qb_raw, result.qb_mapping), qb_headers, "SOURCE TOTAL")
    _write_total_row(ws, inf_total_row, inf_start, inf_end, _source_totals(result.inf_raw, result.inf_mapping), inf_headers, "SOURCE TOTAL")
    _apply_number_formats(ws, qb_headers, data_row, qb_total_row, qb_start,
                          {result.qb_mapping["amount"]}, {result.qb_mapping.get("quantity") or ""})
    _apply_number_formats(ws, inf_headers, data_row, inf_total_row, inf_start,
                          {result.inf_mapping["amount"]}, set())
    ws.column_dimensions[get_column_letter(separator_col)].width = 3.5
    ws.column_dimensions[get_column_letter(separator_col)].fill = PatternFill("solid", fgColor=WHITE)
    _set_widths(ws, qb_start, qb_end, header_row, qb_total_row)
    _set_widths(ws, inf_start, inf_end, header_row, inf_total_row)
    ws.freeze_panes = f"{get_column_letter(inf_start)}{data_row}"
    ws.print_title_rows = "1:3"
    _prepare_sheet(ws)


def _paired_display_frames(result: ReconciliationResult) -> tuple[pd.DataFrame, pd.DataFrame, list[str]]:
    qb_headers = list(result.qb_raw.columns)
    inf_headers = list(result.inf_raw.columns)
    qb_rows, inf_rows, match_results = [], [], []
    for record in result.paired_rows:
        qidx, iidx = record["QB Index"], record["Infinium Index"]
        qb_rows.append(
            [result.qb_work.at[qidx, col] for col in qb_headers]
            if qidx is not None else [None] * len(qb_headers)
        )
        inf_rows.append(
            [result.inf_work.at[iidx, col] for col in inf_headers]
            if iidx is not None else [None] * len(inf_headers)
        )
        match_results.append(record["Match Result"])
    return pd.DataFrame(qb_rows, columns=qb_headers), pd.DataFrame(inf_rows, columns=inf_headers), match_results


def build_reconciled_data_sheet(wb: Workbook, result: ReconciliationResult) -> None:
    ws = wb.create_sheet("Reconciled Data")
    qb_display, inf_display, match_results = _paired_display_frames(result)
    qb_headers = list(qb_display.columns)
    inf_headers = list(inf_display.columns)
    qb_start = 1
    match_col = len(qb_headers) + 1
    inf_start = match_col + 1
    qb_end = len(qb_headers)
    inf_end = inf_start + len(inf_headers) - 1
    header_row, data_row = 3, 4
    final_data_row = data_row + len(match_results) - 1

    _write_title_band(ws, 1, qb_start, qb_end, "QUICKBOOKS | RECONCILED", NAVY)
    _write_title_band(ws, 1, match_col, match_col, "MATCH RESULT", SLATE)
    _write_title_band(ws, 1, inf_start, inf_end, "INFINIUM | RECONCILED", TEAL)
    _write_caption_band(
        ws, 2, qb_start, qb_end,
        f"Every QuickBooks records mapped 1:1. Generated {format_central_timestamp(result.run_timestamp)}.",
        NAVY,
    )
    _write_caption_band(ws, 2, match_col, match_col, "Matching Methodology", SLATE)
    _write_caption_band(ws, 2, inf_start, inf_end, "Infinium records mapped 1:1.", TEAL)
    _write_dataframe_values(ws, qb_display, header_row, qb_start)
    ws.cell(header_row, match_col, "Match Result")
    for offset, value in enumerate(match_results, 1):
        ws.cell(header_row + offset, match_col, value)
    _write_dataframe_values(ws, inf_display, header_row, inf_start)
    _format_header(ws, header_row, qb_start, qb_end, NAVY)
    _format_header(ws, header_row, match_col, match_col, SLATE)
    _format_header(ws, header_row, inf_start, inf_end, TEAL)
    _format_body_block(ws, data_row, final_data_row, qb_start, qb_end, NAVY_LIGHT)
    _format_body_block(ws, data_row, final_data_row, match_col, match_col, SLATE_LIGHT)
    _format_body_block(ws, data_row, final_data_row, inf_start, inf_end, TEAL_LIGHT)

    for offset, record in enumerate(result.paired_rows):
        row = data_row + offset
        status = str(record["Section"])
        if status == "02 Unmatched QuickBooks":
            for col in range(qb_start, match_col + 1):
                ws.cell(row, col).fill = PatternFill("solid", fgColor=AMBER)
        elif status == "03 Unmatched Infinium":
            for col in range(match_col, inf_end + 1):
                ws.cell(row, col).fill = PatternFill("solid", fgColor=ORANGE)
        ws.cell(row, match_col).alignment = Alignment(horizontal="left", vertical="center", wrap_text=True)
        ws.row_dimensions[row].height = 30 if "group-level" in str(record["Match Result"]) else 21

    total_row = final_data_row + 1
    _write_total_row(ws, total_row, qb_start, qb_end,
                     _source_totals(result.qb_raw, result.qb_mapping), qb_headers, "RECONCILED TOTAL")
    _write_total_row(ws, total_row, inf_start, inf_end,
                     _source_totals(result.inf_raw, result.inf_mapping), inf_headers, "RECONCILED TOTAL")
    ws.cell(total_row, match_col, f"Control: {result.metrics['Control Status']}")
    ws.cell(total_row, match_col).fill = PatternFill("solid", fgColor=GREEN_LIGHT if result.metrics["Control Status"] == "PASS" else RED_LIGHT)
    ws.cell(total_row, match_col).font = Font(name="Segoe UI", size=10, bold=True, color=TEXT)
    ws.cell(total_row, match_col).border = _total_border()
    ws.cell(total_row, match_col).alignment = Alignment(horizontal="center", vertical="center")
    _apply_number_formats(ws, qb_headers, data_row, total_row, qb_start,
                          {result.qb_mapping["amount"]}, {result.qb_mapping.get("quantity") or ""})
    _apply_number_formats(ws, inf_headers, data_row, total_row, inf_start,
                          {result.inf_mapping["amount"]}, set())
    _set_widths(ws, qb_start, qb_end, header_row, total_row)
    _set_widths(ws, inf_start, inf_end, header_row, total_row)
    ws.column_dimensions[get_column_letter(match_col)].width = 43
    ws.freeze_panes = f"{get_column_letter(inf_start)}{data_row}"
    ws.auto_filter.ref = f"A{header_row}:{get_column_letter(inf_end)}{final_data_row}"
    ws.print_title_rows = "1:3"
    _prepare_sheet(ws)


def build_fiscal_exception_summary(result: ReconciliationResult) -> pd.DataFrame:
    """Summarize unresolved QuickBooks exceptions by fiscal-period tag."""
    columns = [
        "Fiscal Period", "Period Classification", "Exception Count",
        "Exception Quantity", "Net Exception Amount",
    ]
    if not result.unmatched_qb:
        return pd.DataFrame(columns=columns)

    period_column = result.qb_mapping.get("period")
    if not period_column or period_column not in result.qb_work.columns:
        period_column = str(result.qb_raw.columns[0]) if len(result.qb_raw.columns) else None
    quantity_column = result.qb_mapping.get("quantity")
    selected_period = int(result.metadata.get("fiscal_period", 0) or 0)
    default_year = int(result.metadata.get("fiscal_year", result.run_timestamp.year))
    work = result.qb_work.loc[result.unmatched_qb].copy()
    if period_column:
        work["__PERIOD_NUMBER"] = work[period_column].map(
            lambda value: parse_fiscal_period(value, default_year)[0]
        )
    else:
        work["__PERIOD_NUMBER"] = None
    work["Fiscal Period"] = work["__PERIOD_NUMBER"].map(
        lambda value: f"PD-{int(value):02d}" if pd.notna(value) else "Unspecified"
    )
    work["Period Classification"] = work["__PERIOD_NUMBER"].map(
        lambda value: (
            "Current Reporting Period"
            if pd.notna(value) and int(value) == selected_period
            else "Prior-Period Urgent Exception"
            if pd.notna(value)
            else "Unspecified Period - Review"
        )
    )
    work["__EXCEPTION_QUANTITY"] = (
        pd.to_numeric(work[quantity_column], errors="coerce").fillna(0)
        if quantity_column and quantity_column in work.columns
        else 0.0
    )
    work["__EXCEPTION_AMOUNT"] = work[AMOUNT_CENTS].map(cents_to_float)
    work["__URGENCY_SORT"] = work["Period Classification"].map(
        {
            "Prior-Period Urgent Exception": 1,
            "Unspecified Period - Review": 2,
            "Current Reporting Period": 3,
        }
    )
    summary = (
        work.groupby(
            ["Fiscal Period", "Period Classification", "__URGENCY_SORT", "__PERIOD_NUMBER"],
            as_index=False,
            dropna=False,
        )
        .agg(
            **{
                "Exception Count": (QB_ID, "size"),
                "Exception Quantity": ("__EXCEPTION_QUANTITY", "sum"),
                "Net Exception Amount": ("__EXCEPTION_AMOUNT", "sum"),
            }
        )
        .sort_values(["__URGENCY_SORT", "__PERIOD_NUMBER"], na_position="last")
    )
    return summary.reindex(columns=columns).reset_index(drop=True)


def build_unresolved_sheet(wb: Workbook, result: ReconciliationResult) -> None:
    ws = wb.create_sheet("Unresolved Exceptions")
    source_headers = list(result.qb_raw.columns)
    headers = source_headers + ["Exception Status", "Reference Amount Difference", "Reviewer Note"]
    candidate_map = result.candidates.set_index("QuickBooks Row ID").to_dict("index") if not result.candidates.empty else {}
    records = []
    for qidx in result.unmatched_qb:
        candidate = candidate_map.get(result.qb_work.at[qidx, QB_ID], {})
        records.append(
            [result.qb_work.at[qidx, col] for col in source_headers]
            + [
                candidate.get("Disposition", "Unmatched QuickBooks"),
                candidate.get("Minimum Amount Difference"),
                "",
            ]
        )
    frame = pd.DataFrame(records, columns=headers)
    end_col = len(headers)
    amount_col_position = source_headers.index(result.qb_mapping["amount"]) + 1
    amounts = [cents_or_zero(result.qb_work.at[idx, AMOUNT_CENTS]) for idx in result.unmatched_qb]
    debits = sum(value for value in amounts if value > 0)
    credits = abs(sum(value for value in amounts if value < 0))
    net = sum(amounts)

    _write_title_band(ws, 1, 1, end_col, "ACCOUNTING EXCEPTIONS | JOURNAL ENTRY SUPPORT", NAVY)
    invalid_unresolved = sum(
        1 for idx in result.unmatched_qb if not valid_cents(result.qb_work.at[idx, AMOUNT_CENTS])
    )
    _write_caption_band(
        ws, 2, 1, end_col,
        f"Net signed support total excludes {invalid_unresolved} row(s) with invalid or missing amounts. "
        f"Review every exception before posting. Generated {format_central_timestamp(result.run_timestamp)}.",
        NAVY,
    )
    kpis = [
        ("Unresolved rows", len(result.unmatched_qb), '#,##0'),
        ("Gross debits", cents_to_float(debits), '$#,##0.00;[Red]($#,##0.00);-'),
        ("Credits", cents_to_float(credits), '$#,##0.00;[Red]($#,##0.00);-'),
        ("Proposed JE support total", cents_to_float(net), '$#,##0.00;[Red]($#,##0.00);-'),
    ]
    for idx, (label, value, number_format) in enumerate(kpis):
        start = 1 + idx * 2
        if start > end_col:
            break
        ws.cell(3, start, label)
        ws.cell(4, start, value)
        ws.cell(3, start).font = Font(name="Segoe UI", size=9, bold=True, color=SLATE)
        ws.cell(4, start).font = Font(name="Segoe UI", size=12, bold=True, color=NAVY)
        ws.cell(4, start).number_format = number_format
        for row in (3, 4):
            ws.cell(row, start).fill = PatternFill("solid", fgColor=SLATE_LIGHT)
            ws.cell(row, start).border = _thin_border()

    header_row, data_row = 6, 7
    _write_dataframe_values(ws, frame, header_row, 1)
    _format_header(ws, header_row, 1, end_col, NAVY)
    if len(frame):
        _format_body_block(ws, data_row, data_row + len(frame) - 1, 1, end_col, NAVY_LIGHT)
        for row in range(data_row, data_row + len(frame)):
            ws.cell(row, source_headers.index(result.qb_mapping["amount"]) + 1).number_format = '$#,##0.00;[Red]($#,##0.00);-'
            ws.cell(row, len(source_headers) + 1).fill = PatternFill("solid", fgColor=AMBER)
            ws.cell(row, len(source_headers) + 1).alignment = Alignment(wrap_text=True, vertical="center")
            ws.cell(row, len(source_headers) + 2).number_format = '$#,##0.00;[Red]($#,##0.00);-'
    total_row = data_row + len(frame)
    _write_total_row(
        ws, total_row, 1, end_col,
        {result.qb_mapping["amount"]: cents_to_float(net)}, headers,
        "PROPOSED JE SUPPORT TOTAL",
    )
    ws.cell(total_row, amount_col_position).number_format = '$#,##0.00;[Red]($#,##0.00);-'
    ws.column_dimensions[get_column_letter(len(source_headers) + 1)].width = 48
    ws.column_dimensions[get_column_letter(len(source_headers) + 2)].width = 24
    ws.column_dimensions[get_column_letter(len(source_headers) + 3)].width = 36
    _set_widths(ws, 1, len(source_headers), header_row, total_row)
    ws.freeze_panes = f"A{data_row}"
    if len(frame):
        ws.auto_filter.ref = f"A{header_row}:{get_column_letter(end_col)}{header_row + len(frame)}"
        note_col = get_column_letter(len(source_headers) + 3)
        validation = DataValidation(
            type="textLength", operator="lessThanOrEqual", formula1="1000", allow_blank=True
        )
        validation.error = "Reviewer notes are limited to 1,000 characters."
        validation.errorTitle = "Note too long"
        ws.add_data_validation(validation)
        validation.add(f"{note_col}{data_row}:{note_col}{header_row + len(frame)}")

    journal_amount = abs(cents_to_float(net))
    je_title_row = total_row + 3
    je_caption_row = je_title_row + 1
    je_header_row = je_title_row + 2
    je_data_row = je_header_row + 1
    je_headers = ["Account", "Debit", "Credit", "Entry Basis"]
    je_frame = pd.DataFrame(
        [
            ["Accrued Expenses", journal_amount, 0.0, "Unresolved QuickBooks net exception support"],
            ["Manufactured Sales", 0.0, journal_amount, "Balanced offset"],
        ],
        columns=je_headers,
    )
    _write_title_band(ws, je_title_row, 1, end_col, "PROPOSED JOURNAL ENTRY", SLATE)
    _write_caption_band(
        ws, je_caption_row, 1, end_col,
        "Post only after review and approval. Debit Accrued Expenses and credit Manufactured Sales for the "
        "absolute unresolved net amount; evaluate reversals and negative source values before posting.",
        SLATE,
    )
    _write_dataframe_values(ws, je_frame, je_header_row, 1)
    _format_header(ws, je_header_row, 1, len(je_headers), SLATE)
    _format_body_block(ws, je_data_row, je_data_row + len(je_frame) - 1, 1, len(je_headers), SLATE_LIGHT)
    for row in range(je_data_row, je_data_row + len(je_frame)):
        ws.cell(row, 2).number_format = '$#,##0.00;[Red]($#,##0.00);-'
        ws.cell(row, 3).number_format = '$#,##0.00;[Red]($#,##0.00);-'
    je_total_row = je_data_row + len(je_frame)
    _write_total_row(
        ws, je_total_row, 1, len(je_headers),
        {"Debit": journal_amount, "Credit": journal_amount}, je_headers, "BALANCED TOTAL",
    )
    ws.column_dimensions["A"].width = max(ws.column_dimensions["A"].width or 0, 26)
    ws.column_dimensions["D"].width = max(ws.column_dimensions["D"].width or 0, 52)

    duplicate_frame = result.duplicate_analysis
    duplicate_headers = list(duplicate_frame.columns)
    duplicate_title_row = je_total_row + 3
    duplicate_header_row = duplicate_title_row + 2
    duplicate_data_row = duplicate_header_row + 1
    duplicate_end_col = len(duplicate_headers)
    section_end_col = max(end_col, duplicate_end_col)
    _write_title_band(
        ws, duplicate_title_row, 1, section_end_col,
        "DUPLICATE MATCHING-KEY REVIEW | QUICKBOOKS AND INFINIUM", TEAL,
    )
    duplicate_caption = (
        f"{len(duplicate_frame):,} repeated matching-key group(s) identified. Review these source values for "
        "duplicate entries or legitimate repeated transactions."
        if len(duplicate_frame)
        else "No repeated PO/invoice/amount matching keys were identified in either dataset."
    )
    _write_caption_band(ws, duplicate_title_row + 1, 1, section_end_col, duplicate_caption, TEAL)
    _write_dataframe_values(ws, duplicate_frame, duplicate_header_row, 1)
    _format_header(ws, duplicate_header_row, 1, duplicate_end_col, TEAL)
    if len(duplicate_frame):
        duplicate_last_row = duplicate_data_row + len(duplicate_frame) - 1
        _format_body_block(ws, duplicate_data_row, duplicate_last_row, 1, duplicate_end_col, TEAL_LIGHT)
        _apply_number_formats(
            ws, duplicate_headers, duplicate_data_row, duplicate_last_row, 1,
            {"Amount"}, set(),
        )
        for row in range(duplicate_data_row, duplicate_last_row + 1):
            ws.cell(row, duplicate_headers.index("Reconciliation Status") + 1).fill = PatternFill(
                "solid", fgColor=ORANGE
            )
        ws.column_dimensions[get_column_letter(duplicate_headers.index("Source Row IDs") + 1)].width = 44
        ws.column_dimensions[get_column_letter(duplicate_headers.index("Reconciliation Status") + 1)].width = 42
    else:
        duplicate_last_row = duplicate_header_row

    fiscal_summary = build_fiscal_exception_summary(result)
    fiscal_headers = list(fiscal_summary.columns)
    fiscal_title_row = duplicate_last_row + 3
    fiscal_caption_row = fiscal_title_row + 1
    fiscal_header_row = fiscal_title_row + 2
    fiscal_data_row = fiscal_header_row + 1
    fiscal_end_col = len(fiscal_headers)
    fiscal_section_end_col = max(end_col, fiscal_end_col)
    selected_period = int(result.metadata.get("fiscal_period", 0) or 0)
    _write_title_band(
        ws, fiscal_title_row, 1, fiscal_section_end_col,
        "FISCAL-PERIOD EXCEPTION SUMMARY | CURRENT VS PRIOR PERIODS", NAVY,
    )
    quantity_note = (
        "Exception quantity is sourced from the mapped QuickBooks quantity column."
        if result.qb_mapping.get("quantity")
        else "No QuickBooks quantity column was mapped; exception quantities are shown as zero."
    )
    _write_caption_band(
        ws, fiscal_caption_row, 1, fiscal_section_end_col,
        f"Selected current reporting period: PD-{selected_period:02d}. Every other valid QuickBooks fiscal "
        f"period is classified as a prior-period urgent exception. {quantity_note}",
        NAVY,
    )
    _write_dataframe_values(ws, fiscal_summary, fiscal_header_row, 1)
    _format_header(ws, fiscal_header_row, 1, fiscal_end_col, NAVY)
    if len(fiscal_summary):
        fiscal_last_row = fiscal_data_row + len(fiscal_summary) - 1
        _format_body_block(ws, fiscal_data_row, fiscal_last_row, 1, fiscal_end_col, NAVY_LIGHT)
        for offset, classification in enumerate(fiscal_summary["Period Classification"], start=fiscal_data_row):
            fill = (
                RED_LIGHT
                if classification == "Prior-Period Urgent Exception"
                else GREEN_LIGHT
                if classification == "Current Reporting Period"
                else AMBER
            )
            for col in range(1, fiscal_end_col + 1):
                ws.cell(offset, col).fill = PatternFill("solid", fgColor=fill)
        _apply_number_formats(
            ws, fiscal_headers, fiscal_data_row, fiscal_last_row, 1,
            {"Net Exception Amount"}, {"Exception Count", "Exception Quantity"},
        )
    else:
        fiscal_last_row = fiscal_header_row
    fiscal_total_row = fiscal_last_row + 1
    _write_total_row(
        ws, fiscal_total_row, 1, fiscal_end_col,
        {
            "Exception Count": float(fiscal_summary["Exception Count"].sum()) if len(fiscal_summary) else 0,
            "Exception Quantity": float(fiscal_summary["Exception Quantity"].sum()) if len(fiscal_summary) else 0,
            "Net Exception Amount": float(fiscal_summary["Net Exception Amount"].sum()) if len(fiscal_summary) else 0,
        },
        fiscal_headers,
        "TOTAL EXCEPTIONS",
    )
    _set_widths(ws, 1, fiscal_end_col, fiscal_header_row, fiscal_total_row)
    ws.column_dimensions["B"].width = max(ws.column_dimensions["B"].width or 0, 34)
    ws.print_title_rows = "1:6"
    _prepare_sheet(ws)


def build_product_sheet(wb: Workbook, result: ReconciliationResult) -> None:
    ws = wb.create_sheet("Product Aggregate Summary")
    frame = result.product_summary
    headers = ["Product Name", "Product Quantity", "Product Value"]
    _write_title_band(ws, 1, 1, 3, "PRODUCT AGGREGATE SUMMARY", NAVY)
    _write_caption_band(
        ws, 2, 1, 3,
        "Products are classified from the QuickBooks description column. This classification does not influence "
        f"data matching. Generated {format_central_timestamp(result.run_timestamp)}.",
        NAVY,
    )
    _write_dataframe_values(ws, frame.reindex(columns=headers), 3, 1)
    _format_header(ws, 3, 1, 3, NAVY)
    if len(frame):
        _format_body_block(ws, 4, 3 + len(frame), 1, 3, NAVY_LIGHT)
    total_row = 4 + len(frame)
    totals = {
        "Product Quantity": float(frame["Product Quantity"].sum()) if not frame.empty else 0,
        "Product Value": float(frame["Product Value"].sum()) if not frame.empty else 0,
    }
    _write_total_row(ws, total_row, 1, 3, totals, headers)
    _apply_number_formats(ws, headers, 4, total_row, 1, {"Product Value"}, {"Product Quantity"})
    ws.column_dimensions["A"].width = 34
    ws.column_dimensions["B"].width = 20
    ws.column_dimensions["C"].width = 20
    ws.freeze_panes = "A4"
    if len(frame):
        ws.auto_filter.ref = f"A3:C{3 + len(frame)}"
    _prepare_sheet(ws, landscape=False)


def _save_workbook_bytes(wb: Workbook) -> bytes:
    wb.calculation.fullCalcOnLoad = True
    wb.calculation.forceFullCalc = True
    wb.calculation.calcMode = "auto"
    _autofit_workbook_columns(wb)
    buffer = io.BytesIO()
    wb.save(buffer)
    return buffer.getvalue()


def _apply_workbook_run_metadata(wb: Workbook, result: ReconciliationResult) -> None:
    central_timestamp = result.run_timestamp.astimezone(CENTRAL_TIMEZONE)
    excel_timestamp = central_timestamp.replace(tzinfo=None)
    display_timestamp = format_central_timestamp(central_timestamp)
    # Visible report captions carry the controlled Central timestamp. Core
    # properties use the same run time, while page headers/footers are blank so
    # Excel cannot surface a stale or locale-generated tag on printed sheets.
    wb.properties.created = excel_timestamp
    wb.properties.modified = excel_timestamp
    existing_description = wb.properties.description or ""
    wb.properties.description = (
        f"{existing_description} Generated {display_timestamp}. Run ID: {result.run_id}."
    ).strip()
    for ws in wb.worksheets:
        for section in (
            ws.oddHeader, ws.evenHeader, ws.firstHeader,
            ws.oddFooter, ws.evenFooter, ws.firstFooter,
        ):
            section.left.text = None
            section.center.text = None
            section.right.text = None


def build_primary_workbook(result: ReconciliationResult) -> bytes:
    wb = Workbook()
    wb.properties.creator = "Sales Reconciliation Application"
    wb.properties.title = f"Sales Reconciliation {result.run_id}"
    wb.properties.subject = "QuickBooks to Infinium reconciliation and journal-entry support"
    wb.properties.description = "Four-sheet accounting workpaper generated from one controlled reconciliation run."
    build_raw_data_sheet(wb, result)
    build_reconciled_data_sheet(wb, result)
    build_unresolved_sheet(wb, result)
    build_product_sheet(wb, result)
    _apply_workbook_run_metadata(wb, result)
    return _save_workbook_bytes(wb)


def detailed_ledger_dataframe(result: ReconciliationResult) -> pd.DataFrame:
    records: list[dict[str, Any]] = []
    qb_headers = list(result.qb_raw.columns)
    inf_headers = list(result.inf_raw.columns)
    for record in result.paired_rows:
        output = {
            "Run ID": result.run_id,
            "Section": record["Section"],
            "Match ID": record["Match ID"],
            "Match Result": record["Match Result"],
            "Confidence": record["Confidence"],
            "Group Sequence": record["Group Sequence"],
            "Assessment Explanation": record["Explanation"],
        }
        qidx, iidx = record["QB Index"], record["Infinium Index"]
        output["QB | Source Row ID"] = result.qb_work.at[qidx, QB_ID] if qidx is not None else None
        for header in qb_headers:
            output[f"QB | {header}"] = result.qb_work.at[qidx, header] if qidx is not None else None
        output["INF | Source Row ID"] = result.inf_work.at[iidx, INF_ID] if iidx is not None else None
        for header in inf_headers:
            output[f"INF | {header}"] = result.inf_work.at[iidx, header] if iidx is not None else None
        records.append(output)
    return pd.DataFrame(records)


def _add_standard_data_sheet(
    wb: Workbook,
    name: str,
    title: str,
    caption: str,
    frame: pd.DataFrame,
    header_color: str = NAVY,
    chart_column: Optional[str] = None,
) -> Any:
    ws = wb.create_sheet(name)
    end_col = max(len(frame.columns), 1)
    _write_title_band(ws, 1, 1, end_col, title, header_color)
    _write_caption_band(ws, 2, 1, end_col, caption, header_color)
    if frame.empty and len(frame.columns) == 0:
        frame = pd.DataFrame({"Result": ["No records"]})
        end_col = 1
    _write_dataframe_values(ws, frame, 3, 1)
    _format_header(ws, 3, 1, len(frame.columns), header_color)
    if len(frame):
        _format_body_block(ws, 4, 3 + len(frame), 1, len(frame.columns), NAVY_LIGHT)
        _apply_number_formats(ws, list(frame.columns), 4, 3 + len(frame), 1, set(), set())
    _set_widths(ws, 1, len(frame.columns), 3, max(3 + len(frame), 3), maximum=48)
    wrap_terms = ("EXPLANATION", "REQUIREMENT", "DISPOSITION", "MATCH RESULT", "CANDIDATE IDS")
    for col, header in enumerate(frame.columns, 1):
        if any(term in str(header).upper() for term in wrap_terms):
            ws.column_dimensions[get_column_letter(col)].width = 42
            for row in range(4, 4 + len(frame)):
                ws.cell(row, col).alignment = Alignment(horizontal="left", vertical="center", wrap_text=True)
                ws.row_dimensions[row].height = max(ws.row_dimensions[row].height or 20, 32)
    ws.freeze_panes = "A4"
    if len(frame):
        ws.auto_filter.ref = f"A3:{get_column_letter(len(frame.columns))}{3 + len(frame)}"
    if chart_column and chart_column in frame.columns and len(frame):
        data_col = list(frame.columns).index(chart_column) + 1
        category_col = 1
        chart = BarChart()
        chart.type = "bar"
        chart.style = 10
        chart.title = f"{chart_column} by Match Method"
        chart.y_axis.title = "Match Method"
        chart.x_axis.title = chart_column
        chart.height = 7.5
        chart.width = 15
        data = Reference(ws, min_col=data_col, min_row=3, max_row=3 + len(frame))
        categories = Reference(ws, min_col=category_col, min_row=4, max_row=3 + len(frame))
        chart.add_data(data, titles_from_data=True)
        chart.set_categories(categories)
        chart.legend = None
        ws.add_chart(chart, f"{get_column_letter(len(frame.columns) + 2)}3")
    _prepare_sheet(ws)
    return ws


def build_analytics_summary_sheet(wb: Workbook, result: ReconciliationResult) -> None:
    ws = wb.active
    ws.title = "Executive Summary"
    _write_title_band(ws, 1, 1, 8, "RECONCILIATION ANALYTICS | EXECUTIVE SUMMARY", NAVY)
    _write_caption_band(
        ws, 2, 1, 8,
        f"Run ID: {result.run_id} | Generated {format_central_timestamp(result.run_timestamp)} | Control status: {result.metrics['Control Status']}",
        NAVY,
    )
    cards = [
        ("QuickBooks rows", result.metrics["QuickBooks Rows"], '#,##0'),
        ("Infinium rows", result.metrics["Infinium Rows"], '#,##0'),
        ("QB match rate", result.metrics["QuickBooks Match Rate by Row"], '0.0%'),
        ("Unresolved QB amount", result.metrics["Unresolved QuickBooks Amount"], '$#,##0.00;[Red]($#,##0.00);-'),
        ("QB source total", result.metrics["QuickBooks Source Total"], '$#,##0.00;[Red]($#,##0.00);-'),
        ("Infinium source total", result.metrics["Infinium Source Total"], '$#,##0.00;[Red]($#,##0.00);-'),
        ("Matched amount difference", result.metrics["Matched Amount Difference"], '$#,##0.00;[Red]($#,##0.00);-'),
        ("Control status", result.metrics["Control Status"], '@'),
    ]
    for idx, (label, value, number_format) in enumerate(cards):
        row = 4 if idx < 4 else 7
        col = 1 + (idx % 4) * 2
        ws.merge_cells(start_row=row, start_column=col, end_row=row, end_column=col + 1)
        ws.merge_cells(start_row=row + 1, start_column=col, end_row=row + 1, end_column=col + 1)
        ws.cell(row, col, label)
        ws.cell(row + 1, col, excel_safe(value))
        for r in (row, row + 1):
            for c in (col, col + 1):
                ws.cell(r, c).fill = PatternFill("solid", fgColor=SLATE_LIGHT)
                ws.cell(r, c).border = _thin_border()
        ws.cell(row, col).font = Font(name="Segoe UI", size=9, bold=True, color=SLATE)
        ws.cell(row + 1, col).font = Font(
            name="Segoe UI", size=13, bold=True,
            color=NAVY if value != "FAIL" else "9C0006",
        )
        ws.cell(row + 1, col).number_format = number_format

    start = 11
    ws.cell(start, 1, "MODEL STATUS")
    ws.cell(start, 2, result.metrics["Control Status"])
    ws.cell(start, 1).font = Font(name="Segoe UI", size=11, bold=True, color=WHITE)
    ws.cell(start, 1).fill = PatternFill("solid", fgColor=SLATE)
    ws.cell(start, 2).font = Font(name="Segoe UI", size=11, bold=True, color=TEXT)
    ws.cell(start, 2).fill = PatternFill("solid", fgColor=GREEN_LIGHT if result.metrics["Control Status"] == "PASS" else RED_LIGHT)
    _write_dataframe_values(ws, result.controls, start + 2, 1)
    _format_header(ws, start + 2, 1, len(result.controls.columns), SLATE)
    _format_body_block(ws, start + 3, start + 2 + len(result.controls), 1, len(result.controls.columns), SLATE_LIGHT)
    _apply_number_formats(ws, list(result.controls.columns), start + 3, start + 2 + len(result.controls), 1, set(), set())
    status_col = list(result.controls.columns).index("Status") + 1
    if len(result.controls):
        green = PatternFill("solid", fgColor=GREEN_LIGHT)
        red = PatternFill("solid", fgColor=RED_LIGHT)
        ws.conditional_formatting.add(
            f"{get_column_letter(status_col)}{start + 3}:{get_column_letter(status_col)}{start + 2 + len(result.controls)}",
            FormulaRule(formula=[f'{get_column_letter(status_col)}{start + 3}="PASS"'], fill=green),
        )
        ws.conditional_formatting.add(
            f"{get_column_letter(status_col)}{start + 3}:{get_column_letter(status_col)}{start + 2 + len(result.controls)}",
            FormulaRule(formula=[f'{get_column_letter(status_col)}{start + 3}="FAIL"'], fill=red),
        )
    for col in range(1, 9):
        ws.column_dimensions[get_column_letter(col)].width = 18
    ws.freeze_panes = "A3"
    _prepare_sheet(ws)


def build_analytics_workbook(result: ReconciliationResult) -> bytes:
    wb = Workbook()
    wb.properties.creator = "Sales Reconciliation Application"
    wb.properties.title = f"Sales Reconciliation Analytics {result.run_id}"
    wb.properties.subject = "Detailed matching evidence and reconciliation controls"
    build_analytics_summary_sheet(wb, result)
    _add_standard_data_sheet(
        wb, "Match Method Summary", "MATCH METHOD SUMMARY",
        "Distribution of matched and unresolved rows. Percentages use QuickBooks row count as the denominator.",
        result.method_summary, NAVY, chart_column="QuickBooks Rows",
    )
    _add_standard_data_sheet(
        wb, "Detailed Match Ledger", "DETAILED MATCH LEDGER",
        "One record per displayed source line. Every accepted match contains exactly one QuickBooks row and one Infinium row.",
        detailed_ledger_dataframe(result), SLATE,
    )
    _add_standard_data_sheet(
        wb, "Normalization Detail", "NORMALIZATION DETAIL",
        "Original source values and the exact normalized references and signed amounts considered by the matching engine.",
        result.normalization, TEAL,
    )
    _add_standard_data_sheet(
        wb, "Match Assessment", "MATCH ASSESSMENT",
        "One row per accepted match group or unresolved QuickBooks decision, including criteria and evidence.",
        result.assessments, NAVY,
    )
    _add_standard_data_sheet(
        wb, "Exception Analysis", "EXCEPTION ANALYSIS",
        "Unresolved population summarized by source period, reason, and source ledger. Period is reporting metadata only.",
        result.exception_analysis, NAVY,
    )
    _add_standard_data_sheet(
        wb, "Rules and Run Config", "RULES AND RUN CONFIGURATION",
        "Exact rules, file fingerprints, mappings, versions, and parameters used for this run.",
        pd.concat(
            [
                result.config,
                pd.DataFrame([{"Setting": "", "Value": ""}, {"Setting": "MATCHING RULES", "Value": ""}]),
                result.rules.rename(columns={
                    "Priority": "Setting",
                    "Rule": "Value",
                    "Automatic": "Automatic",
                    "Requirement": "Requirement",
                }),
            ],
            ignore_index=True,
        ),
        SLATE,
    )
    _apply_workbook_run_metadata(wb, result)
    return _save_workbook_bytes(wb)


